+const navToggle = document.querySelector(".nav-toggle");
+const navLinks = document.querySelector("#primary-links");
+const filterButtons = document.querySelectorAll(".filter-button");
+const productCards = document.querySelectorAll(".product-card");
+const bagButtons = document.querySelectorAll(".add-to-bag");
+const bagStatus = document.querySelector("#bag-status");
+const newsletterForm = document.querySelector(".newsletter-form");
+const emailInput = document.querySelector("#email");
+const emailError = document.querySelector("#email-error");
+const formSuccess = document.querySelector("#form-success");
+const timerParts = {
+  hours: document.querySelector("#hours"),
+  minutes: document.querySelector("#minutes"),
+  seconds: document.querySelector("#seconds"),
+};
+
+navToggle.addEventListener("click", () => {
+  const isOpen = navToggle.getAttribute("aria-expanded") === "true";
+  navToggle.setAttribute("aria-expanded", String(!isOpen));
+  navLinks.classList.toggle("is-open", !isOpen);
+});
+
+navLinks.addEventListener("click", (event) => {
+  if (event.target.matches("a")) {
+    navToggle.setAttribute("aria-expanded", "false");
+    navLinks.classList.remove("is-open");
+  }
+});
+
+document.addEventListener("keydown", (event) => {
+  if (event.key === "Escape" && navLinks.classList.contains("is-open")) {
+    navToggle.setAttribute("aria-expanded", "false");
+    navLinks.classList.remove("is-open");
+    navToggle.focus();
+  }
+});
+
+filterButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const filter = button.dataset.filter;
+
+    filterButtons.forEach((item) => {
+      const isActive = item === button;
+      item.classList.toggle("is-active", isActive);
+      item.setAttribute("aria-pressed", String(isActive));
+    });
+
+    productCards.forEach((card) => {
+      const shouldShow = filter === "all" || card.dataset.category === filter;
+      card.classList.toggle("is-hidden", !shouldShow);
+    });
+  });
+});
+
+bagButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const product = button.dataset.product;
+    bagStatus.textContent = `${product} added to your bag.`;
+  });
+});
+
+const dealEndsAt = Date.now() + 12 * 60 * 60 * 1000;
+
+function updateTimer() {
+  const remaining = Math.max(0, dealEndsAt - Date.now());
+  const hours = Math.floor(remaining / 3_600_000);
+  const minutes = Math.floor((remaining % 3_600_000) / 60_000);
+  const seconds = Math.floor((remaining % 60_000) / 1_000);
+
+  timerParts.hours.textContent = String(hours).padStart(2, "0");
+  timerParts.minutes.textContent = String(minutes).padStart(2, "0");
+  timerParts.seconds.textContent = String(seconds).padStart(2, "0");
+}
+
+updateTimer();
+setInterval(updateTimer, 1_000);
+
+newsletterForm.addEventListener("submit", (event) => {
